  Lemma pf_case : forall dirs ss' scs scr' kn' hs',
    sym_exec RSEGS pf_fuel true pf_stops (SCR dirs [] []) (SS 0x34ea4 pf_sr [] pf_kn 40) [] = (ss', scs, scr') ->
    s_pc ss' = 0x34df8 ->
    log_covered pf_regions (s_log ss') = true ->
